UPDATE public.exercises e SET
  muscle_groups = g.pm,
  secondary_muscle_groups = g.sm,
  primary_movement_pattern = coalesce(g.pat, e.primary_movement_pattern),
  counts_toward_volume = g.ctv,
  primary_muscle_group = g.label,
  muscle_group = CASE WHEN g.label = 'Other' THEN e.muscle_group ELSE g.mg END,
  equipment = coalesce(CASE r.ec WHEN 'B' THEN 'Barbell' WHEN 'D' THEN 'Dumbbell' WHEN 'C' THEN 'Cable' WHEN 'M' THEN 'Machine'
                                 WHEN 'S' THEN 'Smith Machine' WHEN 'K' THEN 'Kettlebell' WHEN 'W' THEN 'Bodyweight' WHEN 'N' THEN 'Bands' END, e.equipment)
FROM r JOIN g USING (gi)
WHERE left(e.id::text, 8) = r.p8 AND NOT coalesce(e.archived, false);
